using namespace cg3::cgal::internal;

std::vector<std::vector<Point2d>> result;
VD vd;
for (const Point2d& p : sites) {
    vd.insert(Site_2(p.x(), p.y()));
}

for (VD::Face_iterator fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
    if (fit->is_unbounded()) continue;

    std::vector<Point2d> cell;
    for (Ccb_halfedge_circulator cit = fit->ccb_begin(); cit != fit->ccb_end(); ++cit) {
        Point_2 p = cit->vertex()->point();
        cell.emplace_back(p.x(), p.y());
    }
    result.push_back(cell);
}

return result;

